core_reasoning_1:
\section*{Claim}
For any $N\times N$ matrices $M_1,\ldots,M_{N+1}$, the product of $N+1$ traces is a linear combination of contractions containing at most $N$ traces:
\[
\operatorname{tr}M_1\cdots \operatorname{tr}M_{N+1}
=-\sum_{P\ne {\rm id}}(-1)^P\delta_{a_1P(b_1)}\cdots \delta_{a_{N+1}P(b_{N+1})}M_1^{a_1b_1}\cdots M_{N+1}^{a_{N+1}b_{N+1}}.
\]
\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad a_r,b_r\in\{1,\ldots,N\},\quad r=1,\ldots,N+1,\quad \text{and repeated indices are summed}.\\
\text{(P2)}&\quad \varepsilon_{a_1\cdots a_{N+1}}\varepsilon_{b_1\cdots b_{N+1}}M_1^{a_1b_1}\cdots M_{N+1}^{a_{N+1}b_{N+1}}=0.\\
\text{(P3)}&\quad \varepsilon_{a_1\cdots a_{N+1}}\varepsilon_{b_1\cdots b_{N+1}}
=\delta_{a_1b_1}\cdots\delta_{a_{N+1}b_{N+1}}+\sum_{P\ne {\rm id}}(-1)^P\delta_{a_1P(b_1)}\cdots\delta_{a_{N+1}P(b_{N+1})}.\\
\text{(P4)}&\quad \delta_{a_1b_1}\cdots\delta_{a_{N+1}b_{N+1}}M_1^{a_1b_1}\cdots M_{N+1}^{a_{N+1}b_{N+1}}=\prod_{r=1}^{N+1}\operatorname{tr}M_r.
\end{aligned}
\]
\section*{Derivation}
\begin{align}
0
&=\varepsilon_{a_1\cdots a_{N+1}}\varepsilon_{b_1\cdots b_{N+1}}M_1^{a_1b_1}\cdots M_{N+1}^{a_{N+1}b_{N+1}} &&\text{by (P2)}\\
&=\Bigl(\delta_{a_1b_1}\cdots\delta_{a_{N+1}b_{N+1}}+\sum_{P\ne {\rm id}}(-1)^P\delta_{a_1P(b_1)}\cdots\delta_{a_{N+1}P(b_{N+1})}\Bigr)
M_1^{a_1b_1}\cdots M_{N+1}^{a_{N+1}b_{N+1}} &&\text{by (P3)}\\
&=\prod_{r=1}^{N+1}\operatorname{tr}M_r
+\sum_{P\ne {\rm id}}(-1)^P\delta_{a_1P(b_1)}\cdots\delta_{a_{N+1}P(b_{N+1})}M_1^{a_1b_1}\cdots M_{N+1}^{a_{N+1}b_{N+1}} &&\text{by (P4)}.
\end{align}
Rearranging the last equality gives
\begin{align}
\prod_{r=1}^{N+1}\operatorname{tr}M_r
&=-\sum_{P\ne {\rm id}}(-1)^P\delta_{a_1P(b_1)}\cdots\delta_{a_{N+1}P(b_{N+1})}M_1^{a_1b_1}\cdots M_{N+1}^{a_{N+1}b_{N+1}}.
\end{align}
\section*{Final Result}
\[
\boxed{\operatorname{tr}M_1\cdots \operatorname{tr}M_{N+1}
=-\sum_{P\ne {\rm id}}(-1)^P\delta_{a_1P(b_1)}\cdots \delta_{a_{N+1}P(b_{N+1})}M_1^{a_1b_1}\cdots M_{N+1}^{a_{N+1}b_{N+1}}}
\]
\hfill$\blacksquare$

core_reasoning_3:
\section*{Claim}
For $U\in SU(3)$ and integers $i,j,k$, with normalized trace $\operatorname{Tr}A:=\frac13\operatorname{tr}A$,
\[
\operatorname{Tr}U^i\operatorname{Tr}U^j\operatorname{Tr}U^k
=-\frac{2}{9}\operatorname{Tr}U^{i+j+k}+\frac13\operatorname{Tr}U^i\operatorname{Tr}U^{j+k}+\frac13\operatorname{Tr}U^{i+j}\operatorname{Tr}U^k+\frac13\operatorname{Tr}U^{i+k}\operatorname{Tr}U^j+\frac13\operatorname{Tr}U^{j-i}\operatorname{Tr}U^{k-i}-\frac19\operatorname{Tr}U^{j+k-2i}.
\]
\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad U\in SU(3),\quad U^\dagger=U^{-1},\quad U^aU^b=U^{a+b}\text{ for all integers }a,b.\\
\text{(P2)}&\quad \operatorname{Tr}A:=\frac13\operatorname{tr}A.\\
\text{(P3)}&\quad \text{For all }A,B,C\in SU(3),\\
&\quad \operatorname{tr}A\operatorname{tr}B\operatorname{tr}C
=-\operatorname{tr}(CBA)-\operatorname{tr}(ABC)+\operatorname{tr}A\operatorname{tr}(BC)+\operatorname{tr}(AB)\operatorname{tr}C+\operatorname{tr}(AC)\operatorname{tr}B\\
&\quad\quad\quad\quad\quad\quad\quad+\operatorname{tr}(A^\dagger B)\operatorname{tr}(A^\dagger C)-\operatorname{tr}(A^\dagger B A^\dagger C).
\end{aligned}
\]
\section*{Derivation}
Set $A:=U^i$, $B:=U^j$, and $C:=U^k$. Then
\begin{align}
\operatorname{tr}U^i\operatorname{tr}U^j\operatorname{tr}U^k
&=-\operatorname{tr}(U^kU^jU^i)-\operatorname{tr}(U^iU^jU^k)
+\operatorname{tr}U^i\operatorname{tr}(U^jU^k) &&\text{by (P3)}\\
&\quad+\operatorname{tr}(U^iU^j)\operatorname{tr}U^k
+\operatorname{tr}(U^iU^k)\operatorname{tr}U^j
+\operatorname{tr}((U^i)^\dagger U^j)\operatorname{tr}((U^i)^\dagger U^k)\\
&\quad-\operatorname{tr}((U^i)^\dagger U^j (U^i)^\dagger U^k) &&\text{continuing (P3)}\\
&=-\operatorname{tr}U^{i+j+k}-\operatorname{tr}U^{i+j+k}
+\operatorname{tr}U^i\operatorname{tr}U^{j+k} &&\text{by (P1)}\\
&\quad+\operatorname{tr}U^{i+j}\operatorname{tr}U^k
+\operatorname{tr}U^{i+k}\operatorname{tr}U^j
+\operatorname{tr}U^{j-i}\operatorname{tr}U^{k-i}
-\operatorname{tr}U^{j+k-2i} &&\text{by (P1)}\\
&=-2\operatorname{tr}U^{i+j+k}
+\operatorname{tr}U^i\operatorname{tr}U^{j+k}
+\operatorname{tr}U^{i+j}\operatorname{tr}U^k
+\operatorname{tr}U^{i+k}\operatorname{tr}U^j\\
&\quad+\operatorname{tr}U^{j-i}\operatorname{tr}U^{k-i}-\operatorname{tr}U^{j+k-2i} &&\text{combine equal terms}.
\end{align}
Using $\operatorname{tr}A=3\operatorname{Tr}A$ from (P2), the previous line becomes
\begin{align}
27\operatorname{Tr}U^i\operatorname{Tr}U^j\operatorname{Tr}U^k
&=-6\operatorname{Tr}U^{i+j+k}
+9\operatorname{Tr}U^i\operatorname{Tr}U^{j+k}
+9\operatorname{Tr}U^{i+j}\operatorname{Tr}U^k\\
&\quad+9\operatorname{Tr}U^{i+k}\operatorname{Tr}U^j
+9\operatorname{Tr}U^{j-i}\operatorname{Tr}U^{k-i}
-3\operatorname{Tr}U^{j+k-2i} &&\text{substitute }\operatorname{tr}=3\operatorname{Tr}.
\end{align}
Dividing by $27$ yields the normalized identity.
\section*{Final Result}
\[
\boxed{\operatorname{Tr}U^i\operatorname{Tr}U^j\operatorname{Tr}U^k
=-\frac{2}{9}\operatorname{Tr}U^{i+j+k}+\frac13\operatorname{Tr}U^i\operatorname{Tr}U^{j+k}+\frac13\operatorname{Tr}U^{i+j}\operatorname{Tr}U^k+\frac13\operatorname{Tr}U^{i+k}\operatorname{Tr}U^j+\frac13\operatorname{Tr}U^{j-i}\operatorname{Tr}U^{k-i}-\frac19\operatorname{Tr}U^{j+k-2i}}
\]
\hfill$\blacksquare$

core_reasoning_6:
\section*{Claim}
For $SU(2)$, the continuum loop equation closes linearly on single-trace Wilson loops:
\[
D_xW(C_x)=\frac{\lambda}{2}\oint_Cdy_\nu\,\delta^{(d)}(x-y)\left[\frac12W(C_x)+W\left(C^{(1)}_{xy}\circ\overline{C^{(2)}_{yx}}\right)\right],
\]
where $D_x:=\frac{\partial}{\partial x_\mu}\frac{\delta}{\delta\sigma_{\mu\nu}(x)}$ and the overline reverses the orientation of the indicated contour.
\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad D_xW(C_x)=\lambda\oint_Cdy_\nu\,\delta^{(d)}(x-y)\left[W(C^{(1)}_{xy},C^{(2)}_{yx})-\frac14W(C_x)\right].\\
\text{(P2)}&\quad \text{For normalized }SU(2)\text{ Wilson loops, }W(C_1,C_2)=\frac12W(C_1\circ C_2)+\frac12W(C_1\circ\overline{C_2}).\\
\text{(P3)}&\quad C_x=C^{(1)}_{xy}\circ C^{(2)}_{yx}.\\
\text{(P4)}&\quad \oint_Cdy_\nu\,\delta^{(d)}(x-y)\text{ is linear in its integrand}.
\end{aligned}
\]
\section*{Derivation}
Let $A:=C^{(1)}_{xy}$ and $B:=C^{(2)}_{yx}$. Then
\begin{align}
W(A,B)
&=\frac12W(A\circ B)+\frac12W(A\circ\overline B) &&\text{by (P2)}\\
&=\frac12W(C_x)+\frac12W\left(C^{(1)}_{xy}\circ\overline{C^{(2)}_{yx}}\right) &&\text{by (P3)}.
\end{align}
Substitute this into the $SU(N)$ equation specialized to $N=2$:
\begin{align}
D_xW(C_x)
&=\lambda\oint_Cdy_\nu\,\delta^{(d)}(x-y)\left[\frac12W(C_x)+\frac12W\left(C^{(1)}_{xy}\circ\overline{C^{(2)}_{yx}}\right)-\frac14W(C_x)\right] &&\text{by (P1)}\\
&=\lambda\oint_Cdy_\nu\,\delta^{(d)}(x-y)\left[\frac14W(C_x)+\frac12W\left(C^{(1)}_{xy}\circ\overline{C^{(2)}_{yx}}\right)\right] &&\text{combine }W(C_x)\\
&=\frac{\lambda}{2}\oint_Cdy_\nu\,\delta^{(d)}(x-y)\left[\frac12W(C_x)+W\left(C^{(1)}_{xy}\circ\overline{C^{(2)}_{yx}}\right)\right] &&\text{factor }\frac12\text{ by (P4)}.
\end{align}
\section*{Final Result}
\[
\boxed{D_xW(C_x)=\frac{\lambda}{2}\oint_Cdy_\nu\,\delta^{(d)}(x-y)\left[\frac12W(C_x)+W\left(C^{(1)}_{xy}\circ\overline{C^{(2)}_{yx}}\right)\right]}
\]
\hfill$\blacksquare$

core_reasoning_8:
\section*{Claim}
For a reflection $\Theta$ splitting lattice variables into positive and reflected halves, if the Wilson-action boundary factor has a positive expansion into reflected pairs, then every positive-side operator $O^+$ obeys reflection positivity:
\[
\int DU\,O^+\Theta O^+\,e^{-S}\ge0.
\]
\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad \Theta^2=1,\quad \Theta(AB)=\Theta A\,\Theta B,\quad \Theta\text{ maps the positive half of the lattice to the negative half}.\\
\text{(P2)}&\quad e^{-S}=e^{-S_+}\Theta(e^{-S_+})e^{-S_\Delta}.\\
\text{(P3)}&\quad e^{-S_\Delta}=\sum_{\ell}c_\ell B_\ell^+\Theta B_\ell^+\quad\text{with }c_\ell\ge0\text{ and }B_\ell^+\text{ supported on the positive half}.\\
\text{(P4)}&\quad \int DU\,A^+\Theta A^+=\left\|\int DU^+A^+\right\|^2\ge0\text{ for every positive-side }A^+.\\
\text{(P5)}&\quad O^+\text{ is supported on the positive half of the lattice}.
\end{aligned}
\]
\section*{Derivation}
\begin{align}
\int DU\,O^+\Theta O^+\,e^{-S}
&=\int DU\,O^+\Theta O^+\,e^{-S_+}\Theta(e^{-S_+})e^{-S_\Delta} &&\text{by (P2)}\\
&=\int DU\,O^+e^{-S_+}\Theta(O^+e^{-S_+})e^{-S_\Delta} &&\text{by (P1)}\\
&=\int DU\,O^+e^{-S_+}\Theta(O^+e^{-S_+})\sum_\ell c_\ell B_\ell^+\Theta B_\ell^+ &&\text{by (P3)}\\
&=\sum_\ell c_\ell\int DU\,O^+e^{-S_+}B_\ell^+\Theta(O^+e^{-S_+}B_\ell^+) &&\text{by linearity and (P1)}.
\end{align}
Define $A_\ell^+:=O^+e^{-S_+}B_\ell^+$. Then
\begin{align}
\int DU\,O^+\Theta O^+\,e^{-S}
&=\sum_\ell c_\ell\int DU\,A_\ell^+\Theta A_\ell^+ &&\text{definition of }A_\ell^+\\
&=\sum_\ell c_\ell\left\|\int DU^+A_\ell^+\right\|^2 &&\text{by (P4)}\\
&\ge0 &&\text{because }c_\ell\ge0\text{ and each norm square is nonnegative}.
\end{align}
\section*{Final Result}
\[
\boxed{\int DU\,O^+\Theta O^+\,e^{-S}\ge0}
\]
\hfill$\blacksquare$

core_reasoning_9:
\section*{Claim}
If all finite-$N$ bootstrap constraints consist of linear Makeenko--Migdal equations and positive-semidefinite constraints whose entries depend affinely on Wilson-loop variables, then the feasible set is convex; hence optimizing any linear Wilson-loop observable over that set is a semidefinite program.
\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad w\in\mathbb{R}^q\text{ denotes the vector of retained Wilson-loop variables}.\\
\text{(P2)}&\quad \text{The loop equations have the linear form }Aw=b.\\
\text{(P3)}&\quad \text{Each positivity constraint has the affine form }M_r(w):=M_{r,0}+\sum_{j=1}^qw_jM_{r,j}\succeq0.\\
\text{(P4)}&\quad X\succeq0\text{ and }Y\succeq0\Longrightarrow tX+(1-t)Y\succeq0\text{ for every }t\in[0,1].\\
\text{(P5)}&\quad \mathcal F:=\{w\in\mathbb{R}^q:Aw=b\text{ and }M_r(w)\succeq0\text{ for all }r\}.\\
\text{(P6)}&\quad \text{The optimization objective is }\ell(w):=c^Tw\text{ for a fixed }c\in\mathbb{R}^q.
\end{aligned}
\]
\section*{Derivation}
Let $w^{(1)},w^{(2)}\in\mathcal F$ and $t\in[0,1]$. Define $w^{(t)}:=tw^{(1)}+(1-t)w^{(2)}$. Then
\begin{align}
Aw^{(t)}
&=A\bigl(tw^{(1)}+(1-t)w^{(2)}\bigr) &&\text{definition of }w^{(t)}\\
&=tAw^{(1)}+(1-t)Aw^{(2)} &&\text{linearity of }A\\
&=tb+(1-t)b &&\text{since }w^{(1)},w^{(2)}\in\mathcal F\text{ by (P5)}\\
&=b. &&\text{combine coefficients}
\end{align}
For each positivity block $r$,
\begin{align}
M_r(w^{(t)})
&=M_{r,0}+\sum_{j=1}^q\bigl(tw^{(1)}_j+(1-t)w^{(2)}_j\bigr)M_{r,j} &&\text{by (P3)}\\
&=t\left(M_{r,0}+\sum_{j=1}^qw^{(1)}_jM_{r,j}\right)+(1-t)\left(M_{r,0}+\sum_{j=1}^qw^{(2)}_jM_{r,j}\right) &&\text{since }t+(1-t)=1\\
&=tM_r(w^{(1)})+(1-t)M_r(w^{(2)}) &&\text{by (P3)}\\
&\succeq0 &&\text{by (P4) and }w^{(1)},w^{(2)}\in\mathcal F.
\end{align}
Therefore $w^{(t)}$ satisfies every constraint, so
\begin{align}
w^{(1)},w^{(2)}\in\mathcal F,\\ t\in[0,1]
&\Longrightarrow tw^{(1)}+(1-t)w^{(2)}\in\mathcal F &&\text{by the two preceding displays}\\
&\Longrightarrow \mathcal F\text{ is convex}. &&\text{definition of convexity}
\end{align}
Because the objective is linear by (P6) and the constraints are linear equalities plus affine positive-semidefinite conditions, the optimization is a semidefinite program.
\section*{Final Result}
\[
\boxed{\mathcal F\text{ is convex, and }\min_{w\in\mathcal F}c^Tw\text{ or }\max_{w\in\mathcal F}c^Tw\text{ is a semidefinite program}}
\]
\hfill$\blacksquare$
